 * under the License.
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <debug.h>
#include <stdint.h>

#include <nuttx/board.h>
#include <sys/boardctl.h>

#include "arm_internal.h"

#include "bk7258_memorymap.h"
#include "bk7258_reset.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define BK7258_AON_PMU_R0     (BK7258_AON_PMU_BASE + (0x00 << 2))
#define BK7258_AON_PMU_R25    (BK7258_AON_PMU_BASE + (0x25 << 2))
#define BK7258_AON_PMU_R7A    (BK7258_AON_PMU_BASE + (0x7a << 2))

/* Reset reason occupies R0/R7A bits [30:24] */

#define BK7258_RESET_SHIFT    24
#define BK7258_RESET_MASK     0x7f

/* The two magic words that latch R0 into the retained shadow */

#define BK7258_PMU_COMMIT0    0x424b55aa
#define BK7258_PMU_COMMIT1    0xbdb4aa55

/* Vendor reason codes, from include/components/system.h of the Beken SDK.
 * Only the ones this port can actually produce or observe are named.
 */

#define BK_RESET_POWERON      0x00
#define BK_RESET_REBOOT       0x01
#define BK_RESET_WATCHDOG     0x02
#define BK_RESET_DEEPPS_GPIO  0x03
#define BK_RESET_DEEPPS_RTC   0x04
#define BK_RESET_DEEPPS_USB   0x05
#define BK_RESET_DEEPPS_TOUCH 0x06
#define BK_RESET_CRASH_FIRST  0x07  /* 0x07..0x0e are the crash codes */
#define BK_RESET_CRASH_LAST   0x0e
#define BK_RESET_SUPER_DEEP   0x0f
#define BK_RESET_NMI_WDT      0x10

/****************************************************************************
 * Private Data
 ****************************************************************************/

/* Latched once in bk7258_reset_cause_latch(); the hardware field is
 * rewritten immediately afterwards, so this is the only surviving copy.
 */

static uint8_t g_reset_reason = BK_RESET_POWERON;
static bool    g_reset_latched;

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: bk7258_reset_reason_set
 *
 * Description:
 *   Record why the board is about to reset, so the next boot can report it.
 *   Read-modify-write: R0 carries unrelated always-on state in the bits
 *   outside [30:24] and clobbering them would be a power-domain change.
 *
 ****************************************************************************/

void bk7258_reset_reason_set(uint32_t reason)
{
  uint32_t regval = getreg32(BK7258_AON_PMU_R0);

  regval &= ~(BK7258_RESET_MASK << BK7258_RESET_SHIFT);
  regval |= (reason & BK7258_RESET_MASK) << BK7258_RESET_SHIFT;
  putreg32(regval, BK7258_AON_PMU_R0);

  /* Commit R0 into the retained shadow.  Both words, in this order. */

  putreg32(BK7258_PMU_COMMIT0, BK7258_AON_PMU_R25);
  putreg32(BK7258_PMU_COMMIT1, BK7258_AON_PMU_R25);
}

/****************************************************************************
 * Name: bk7258_reset_cause_latch
 *
 * Description:
 *   Read and cache the reason this boot happened, then arm the field with
 *   "power on" so that an unannounced reset -- a watchdog bite that nobody
 *   asked for, a brown-out -- is not mistaken for whatever the previous
 *   boot last wrote.  Anything intentional overwrites it on the way out
 *   through bk7258_reset_reason_set().
 *
 *   Call once, from board_late_initialize(), after the AON domain is known
 *   good.  Safe to call again; subsequent calls do nothing.
 *
 ****************************************************************************/

void bk7258_reset_cause_latch(void)
{
  uint32_t regval;

  if (g_reset_latched)
    {
      return;
    }

  regval = getreg32(BK7258_AON_PMU_R7A);
  g_reset_reason = (regval >> BK7258_RESET_SHIFT) & BK7258_RESET_MASK;
  g_reset_latched = true;

  binfo("BK7258 reset reason: 0x%02x (PMU R7A 0x%08" PRIx32 ")\n",
        g_reset_reason, regval);

  bk7258_reset_reason_set(BK_RESET_POWERON);
}

/****************************************************************************
 * Name: board_reset_cause
 *
 * Description:
 *   boardctl(BOARDIOC_RESET_CAUSE) back end.  Maps the vendor reason code
 *   onto the NuttX enumeration.
 *
 *   The watchdog on this SoC is the always-on one at 0x44000600 -- there is
 *   no separate main watchdog -- so a bite maps to SYS_RWDT, which is the
 *   value the xTS watchdog case expects.
 *
 ****************************************************************************/

#ifdef CONFIG_BOARDCTL_RESET_CAUSE
int board_reset_cause(FAR struct boardioc_reset_cause_s *cause)
{
  if (cause == NULL)
    {
      return -EINVAL;
    }

  cause->flag = 0;

  switch (g_reset_reason)
    {
      case BK_RESET_POWERON:
        cause->cause = BOARDIOC_RESETCAUSE_SYS_CHIPPOR;
        break;

      case BK_RESET_REBOOT:
        cause->cause = BOARDIOC_RESETCAUSE_CORE_SOFT;
        cause->flag = BOARDIOC_SOFTRESETCAUSE_USER_REBOOT;
        break;

      case BK_RESET_WATCHDOG:
      case BK_RESET_NMI_WDT:
        cause->cause = BOARDIOC_RESETCAUSE_SYS_RWDT;
        break;

      case BK_RESET_DEEPPS_GPIO:
      case BK_RESET_DEEPPS_RTC:
      case BK_RESET_DEEPPS_USB:
      case BK_RESET_DEEPPS_TOUCH:
      case BK_RESET_SUPER_DEEP:
        cause->cause = BOARDIOC_RESETCAUSE_CORE_DPSP;
        break;

      default:
        if (g_reset_reason >= BK_RESET_CRASH_FIRST &&
            g_reset_reason <= BK_RESET_CRASH_LAST)
          {
            /* The vendor crash codes all mean "the previous image took a
             * fault and reset itself", which is a software core reset.
             */

            cause->cause = BOARDIOC_RESETCAUSE_CORE_SOFT;
            cause->flag = BOARDIOC_SOFTRESETCAUSE_PANIC;
          }
        else
          {
            cause->cause = BOARDIOC_RESETCAUSE_UNKOWN;
            cause->flag = g_reset_reason;
          }
        break;
    }

  return OK;
}
#endif /* CONFIG_BOARDCTL_RESET_CAUSE */

