	s_wdt_driver_is_init = true;

	return BK_OK;
}

bk_err_t bk_wdt_driver_deinit(void)
{
	if (!s_wdt_driver_is_init) {
		return BK_OK;
	}
	wdt_deinit_common();
#if (CONFIG_SYS_CPU0)
