  bk7258_reset_reason_set(BK7258_RESET_WATCHDOG);

  bk7258_nmi_wdt_arm(0);
  bk7258_wdt_arm(BK7258_WDT_PERIOD_DUMP);

  PANIC();

  return OK;
}

