/****************************************************************************
 * board/contest_board/src/sigtest.c
 *
 * Why Ctrl-C does not interrupt anything on this console.
 *
 * The chain is entirely inside the serial driver: uart_recvchars() calls
 * uart_check_special() on every received chunk, which returns SIGINT when
 * the byte matches CONFIG_TTY_SIGINT_CHAR, and uart_recvchars() then does
 * nxsig_tgkill(-1, dev->pid, signo).  Two gates gate it, and neither is
 * visible from userspace by inspection:
 *
 *   dev->tc_lflag & ISIG   set by uart_register() for a console device
 *   dev->pid > 0           set by the TIOCSCTTY ioctl
 *
 * Reading the sources says both should hold on this board.  They evidently
 * do not, so this asks the driver directly: tcgetattr() exposes c_lflag, and
 * the return value of a TIOCSCTTY says whether the pid slot was free -- it
 * rejects the call when one is already registered, which is how a stale
 * registration would show up.
 *
 * Then it waits, so that a Ctrl-C typed now either kills it or does not.
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * Licensed to the Apache Software Foundation (ASF) under one or more
 * contributor license agreements.  See the NOTICE file distributed with
 * this work for additional information regarding copyright ownership.  The
 * ASF licenses this file to you under the Apache License, Version 2.0 (the
 * "License"); you may not use this file except in compliance with the
 * License.  You may obtain a copy of the License at
 *
 *   http://www.apache.org/licenses/LICENSE-2.0
 *
 * Unless required by applicable law or agreed to in writing, software
 * distributed under the License is distributed on an "AS IS" BASIS, WITHOUT
 * WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.  See the
 * License for the specific language governing permissions and limitations
 * under the License.
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <string.h>
#include <sys/ioctl.h>
#include <termios.h>
#include <unistd.h>

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  FAR const char *path = "/dev/console";
  struct termios term;
  int seconds = 20;
  int claim = 1;
  int fd;
  int ret;
  int i;

  for (i = 1; i < argc; i++)
    {
      if (strcmp(argv[i], "-d") == 0 && i + 1 < argc)
        {
          path = argv[++i];
        }
      else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc)
        {
          seconds = atoi(argv[++i]);
        }
      else if (strcmp(argv[i], "-n") == 0)
        {
          claim = 0;      /* skip TIOCSCTTY, rely on whoever holds it */
        }
      else
        {
          printf("Usage: sigtest [-d dev] [-t seconds] [-n]\n");
          return ERROR;
        }
    }

  fd = open(path, O_RDWR);
  if (fd < 0)
    {
      printf("sigtest: open %s failed: %d\n", path, errno);
      return ERROR;
    }

  printf("sigtest: %s, pid %d\n", path, (int)getpid());

  ret = tcgetattr(fd, &term);
  if (ret < 0)
    {
      printf("  tcgetattr failed: %d (%s)\n", errno, strerror(errno));
    }
  else
    {
      printf("  c_lflag = 0x%08lx   ISIG=%s ICANON=%s ECHO=%s\n",
             (unsigned long)term.c_lflag,
             (term.c_lflag & ISIG)   ? "yes" : "NO",
             (term.c_lflag & ICANON) ? "yes" : "no",
             (term.c_lflag & ECHO)   ? "yes" : "no");
    }

  if (claim)
    {
      ret = ioctl(fd, TIOCSCTTY, getpid());
      if (ret < 0)
        {
          printf("  TIOCSCTTY -> %d, errno %d (%s)"
                 "  [EINVAL here means a pid is already registered]\n",
                 ret, errno, strerror(errno));
        }
      else
        {
          printf("  TIOCSCTTY -> ok, this task now owns the tty\n");
        }
    }
  else
    {
      printf("  TIOCSCTTY skipped (-n)\n");
    }

  printf("  waiting %d s -- press Ctrl-C now\n", seconds);
  fflush(stdout);

  for (i = 0; i < seconds; i++)
    {
      sleep(1);
      printf(".");
      fflush(stdout);
    }

  printf("\n  survived %d s: no SIGINT was delivered\n", seconds);

  if (claim)
    {
      ioctl(fd, TIOCNOTTY, 0);
    }

  close(fd);
  return OK;
}

